settings.custom_css:
selector {
  border-top: 6px solid #FFC901;
}
/* =========================
   TARJETA PONENTE
   ========================= */

.ponente-card {
    position: relative !important;
    overflow: hidden !important;
}


/* CAPA OSCURA QUE APARECE AL PASAR EL MOUSE */
.ponente-card .ponente-hover {
    position: absolute !important;
    inset: 0 !important;

    width: 100% !important;
    height: 100% !important;

    margin: 0 !important;
    padding: 35px !important;

    background: rgba(0, 20, 45, 0.82) !important;

    border: 1px solid rgba(255, 204, 0, 0.85) !important;
    box-sizing: border-box !important;

    z-index: 20 !important;

    /* CENTRADO */
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    /* OCULTO NORMALMENTE */
    opacity: 0;
    visibility: hidden;

    transition: opacity 0.35s ease, visibility 0.35s ease;

    pointer-events: none;
}


/* MOSTRAR AL PASAR EL MOUSE */
.ponente-card:hover .ponente-hover {
    opacity: 1;
    visibility: visible;
}


/* CONTENEDOR INTERNO DE ELEMENTOR */
.ponente-card .ponente-hover .elementor-widget-container {
    width: 100% !important;
    height: auto !important;

    margin: 0 !important;
    padding: 0 !important;

    text-align: center !important;
}


/* TEXTO */
.ponente-card .ponente-hover,
.ponente-card .ponente-hover p {
    color: #ffffff !important;
    font-size: 16px !important;
    line-height: 1.55 !important;
    font-weight: 400 !important;
}


/* QUITAR MÁRGENES DE PÁRRAFOS */
.ponente-card .ponente-hover p {
    margin: 0 !important;
}


/* =========================
   MÓVIL
   ========================= */

@media (max-width: 767px) {

    .ponente-card .ponente-hover {
        padding: 22px !important;
    }

    .ponente-card .ponente-hover,
    .ponente-card .ponente-hover p {
        font-size: 14px !important;
        line-height: 1.45 !important;
    }
}

selector .titulo {
  margin: 0;
  text-align: left;
  font: normal normal 600 32px/64px Montserrat, sans-serif;
  letter-spacing: 0;
  color: #253054;
}

selector .fuerte {
  font-weight: 700;
}

selector .parrafo {
  max-width: 484px;
  margin: 0;
  text-align: left;
  font: normal normal 400 19px/32px Inter, sans-serif;
  letter-spacing: 0;
  color: #0A0F15;
}

selector .parrafo strong {
  font-weight: 700;
}

selector .divisor {
  height: 0;
  max-width: 484px;
  margin: 32px 0;
  border: none;
  border-top: 1px solid #D8DEE8;
}

@media (max-width: 767px) {
  selector .titulo {
    font-size: 26px;
    line-height: 40px;
  }
  selector .parrafo {
    font-size: 17px;
    line-height: 28px;
  }
  selector .divisor {
    margin: 24px 0;
  }
}
